/**
 * Demo scenarios: A2UI v0.9 message streams exactly as an agent would send them.
 *
 * Scenario 1 is the JSON generated by the A2UI Composer (https://a2ui-composer.ag-ui.com) for a
 * social profile card - pasted verbatim, targeting the standard Basic Catalog.
 *
 * Scenario 2 re-expresses the same card with the CUSTOM catalog (ProfileHeader, StatTile,
 * ChipStrip, `initials()` function, collection-bound template children).
 *
 * Scenario 3 is a form that exercises two-way bindings + client-side `checks` validation.
 */
import {BASIC_CATALOG_ID, SOCIAL_CATALOG_ID} from './a2ui/catalog';

export type A2uiMessage = Record<string, unknown>;

export interface Scenario {
  id: string;
  title: string;
  subtitle: string;
  surfaceId: string;
  messages: A2uiMessage[];
}

// ---------------------------------------------------------------------------
// Scenario 1 - A2UI Composer output (Basic Catalog), verbatim
// ---------------------------------------------------------------------------
export const composerComponents = [
  {id: 'root', component: 'Card', child: 'main-column'},
  {id: 'main-column', component: 'Column', children: ['header', 'info', 'bio', 'stats-row', 'follow-btn'], align: 'center'},
  {id: 'header', component: 'Image', url: {path: '/avatar'}, fit: 'cover', variant: 'avatar'},
  {id: 'info', component: 'Column', children: ['name', 'username'], align: 'center'},
  {id: 'name', component: 'Text', text: {path: '/name'}, variant: 'h2'},
  {id: 'username', component: 'Text', text: {path: '/username'}, variant: 'caption'},
  {id: 'bio', component: 'Text', text: {path: '/bio'}, variant: 'body'},
  {id: 'stats-row', component: 'Row', children: ['followers-col', 'following-col', 'posts-col'], justify: 'spaceAround'},
  {id: 'followers-col', component: 'Column', children: ['followers-count', 'followers-label'], align: 'center'},
  {
    id: 'followers-count',
    component: 'Text',
    text: {call: 'formatNumber', args: {value: {path: '/followers'}}, returnType: 'string'},
    variant: 'h3',
  },
  {id: 'followers-label', component: 'Text', text: 'Followers', variant: 'caption'},
  {id: 'following-col', component: 'Column', children: ['following-count', 'following-label'], align: 'center'},
  {
    id: 'following-count',
    component: 'Text',
    text: {call: 'formatNumber', args: {value: {path: '/following'}}, returnType: 'string'},
    variant: 'h3',
  },
  {id: 'following-label', component: 'Text', text: 'Following', variant: 'caption'},
  {id: 'posts-col', component: 'Column', children: ['posts-count', 'posts-label'], align: 'center'},
  {
    id: 'posts-count',
    component: 'Text',
    text: {call: 'formatNumber', args: {value: {path: '/posts'}}, returnType: 'string'},
    variant: 'h3',
  },
  {id: 'posts-label', component: 'Text', text: 'Posts', variant: 'caption'},
  {id: 'follow-btn-text', component: 'Text', text: {path: '/followText'}},
  {id: 'follow-btn', component: 'Button', child: 'follow-btn-text', action: {event: {name: 'follow', context: {}}}},
];

export const composerData = {
  avatar: 'https://images.unsplash.com/photo-1494790108377-be9c29b29330?w=150&h=150&fit=crop',
  name: 'Sarah Chen',
  username: '@sarahchen',
  bio: 'Product Designer at Tech Co. Creating delightful experiences.',
  followers: 12400,
  following: 892,
  posts: 347,
  followText: 'Follow',
};

const composerScenario: Scenario = {
  id: 'composer',
  title: '1 · Composer output → Basic Catalog',
  subtitle: 'Verbatim JSON from a2ui-composer. Standard 18-component catalog, formatNumber(), Button → event.',
  surfaceId: 'profile_basic',
  messages: [
    {version: 'v0.9', createSurface: {surfaceId: 'profile_basic', catalogId: BASIC_CATALOG_ID}},
    {version: 'v0.9', updateComponents: {surfaceId: 'profile_basic', components: composerComponents}},
    {version: 'v0.9', updateDataModel: {surfaceId: 'profile_basic', path: '/', value: composerData}},
  ],
};

// ---------------------------------------------------------------------------
// Scenario 2 - Same card using the CUSTOM catalog
// ---------------------------------------------------------------------------
const customScenario: Scenario = {
  id: 'custom',
  title: '2 · Custom catalog components',
  subtitle: 'ProfileHeader + ChipStrip + StatTile, custom initials() function, collection-bound template (recent posts).',
  surfaceId: 'profile_custom',
  messages: [
    {version: 'v0.9', createSurface: {surfaceId: 'profile_custom', catalogId: SOCIAL_CATALOG_ID}},
    {
      version: 'v0.9',
      updateComponents: {
        surfaceId: 'profile_custom',
        components: [
          {id: 'root', component: 'Card', child: 'col'},
          {id: 'col', component: 'Column', children: ['hdr', 'bio', 'strip', 'div', 'posts-title', 'posts', 'actions']},
          // ---- custom: ProfileHeader with a trailing Button
          {
            id: 'hdr',
            component: 'ProfileHeader',
            avatarUrl: {path: '/avatar'},
            name: {path: '/name'},
            handle: {path: '/username'},
            verified: {path: '/verified'},
            trailing: 'follow-btn',
          },
          {id: 'follow-btn', component: 'Button', variant: 'primary', child: 'follow-txt', action: {event: {name: 'follow', context: {handle: {path: '/username'}}}}},
          {id: 'follow-txt', component: 'Text', text: {path: '/followText'}},
          {id: 'bio', component: 'Text', text: {path: '/bio'}, variant: 'body'},
          // ---- custom: ChipStrip of StatTiles (each tile has its own action)
          {id: 'strip', component: 'ChipStrip', children: ['t1', 't2', 't3', 't4']},
          {id: 't1', component: 'StatTile', label: 'Followers', value: {path: '/followers'}, accent: 'blue', action: {event: {name: 'open_stat', context: {stat: 'followers'}}}},
          {id: 't2', component: 'StatTile', label: 'Following', value: {path: '/following'}, accent: 'green', action: {event: {name: 'open_stat', context: {stat: 'following'}}}},
          {id: 't3', component: 'StatTile', label: 'Posts', value: {path: '/posts'}, accent: 'purple'},
          {id: 't4', component: 'StatTile', label: 'Likes', value: {path: '/likes'}, accent: 'orange'},
          {id: 'div', component: 'Divider'},
          // ---- custom FUNCTION: initials("Sarah Chen") -> "SC"
          {
            id: 'posts-title',
            component: 'Text',
            variant: 'h4',
            text: {
              call: 'formatString',
              args: {value: 'Recent posts by ${initials(value: /name)}'},
              returnType: 'string',
            },
          },
          // ---- collection-bound template: one 'post-row' per item in /recentPosts
          {id: 'posts', component: 'Column', children: {componentId: 'post-row', path: '/recentPosts'}},
          {id: 'post-row', component: 'Row', justify: 'spaceBetween', align: 'center', children: ['post-title', 'post-likes']},
          {id: 'post-title', component: 'Text', text: {path: 'title'}, variant: 'body'},
          {
            id: 'post-likes',
            component: 'Text',
            variant: 'caption',
            text: {call: 'formatString', args: {value: '♥ ${formatNumber(value: likes)}'}, returnType: 'string'},
          },
          {id: 'actions', component: 'Row', justify: 'end', children: ['msg-btn']},
          {id: 'msg-btn', component: 'Button', variant: 'borderless', child: 'msg-txt', action: {event: {name: 'message', context: {to: {path: '/username'}}}}},
          {id: 'msg-txt', component: 'Text', text: '✉ Message'},
        ],
      },
    },
    {
      version: 'v0.9',
      updateDataModel: {
        surfaceId: 'profile_custom',
        path: '/',
        value: {
          ...composerData,
          verified: true,
          likes: 98213,
          recentPosts: [
            {title: 'Designing for trust in agentic UIs', likes: 1204},
            {title: 'Why declarative beats generated HTML', likes: 877},
            {title: 'Figma → A2UI in 10 minutes', likes: 2311},
          ],
        },
      },
    },
  ],
};

// ---------------------------------------------------------------------------
// Scenario 3 - Form with two-way bindings and client-side checks
// ---------------------------------------------------------------------------
const formScenario: Scenario = {
  id: 'form',
  title: '3 · Form · two-way binding + checks',
  subtitle: 'TextField/ChoicePicker/CheckBox write to the data model; Button is disabled until checks pass.',
  surfaceId: 'dm_form',
  messages: [
    {version: 'v0.9', createSurface: {surfaceId: 'dm_form', catalogId: BASIC_CATALOG_ID}},
    {
      version: 'v0.9',
      updateComponents: {
        surfaceId: 'dm_form',
        components: [
          {id: 'root', component: 'Card', child: 'col'},
          {id: 'col', component: 'Column', children: ['title', 'preview', 'subject', 'tone', 'urgent', 'send']},
          {id: 'title', component: 'Text', variant: 'h3', text: {call: 'formatString', args: {value: 'Message ${/username}'}, returnType: 'string'}},
          {id: 'preview', component: 'Text', variant: 'caption', text: {call: 'formatString', args: {value: 'Live preview → "${/form/subject}"'}, returnType: 'string'}},
          {
            id: 'subject', component: 'TextField', label: 'Subject', value: {path: '/form/subject'},
            checks: [{condition: {call: 'required', args: {value: {path: '/form/subject'}}, returnType: 'boolean'}, message: 'Subject is required'}],
          },
          {
            id: 'tone', component: 'ChoicePicker', label: 'Tone', variant: 'mutuallyExclusive', displayStyle: 'chips', value: {path: '/form/tone'},
            options: [{label: 'Friendly', value: 'friendly'}, {label: 'Professional', value: 'pro'}, {label: 'Short', value: 'short'}],
          },
          {id: 'urgent', component: 'CheckBox', label: 'Mark as urgent', value: {path: '/form/urgent'}},
          {
            id: 'send', component: 'Button', variant: 'primary', child: 'send-txt',
            action: {event: {name: 'send_message', context: {subject: {path: '/form/subject'}, tone: {path: '/form/tone'}, urgent: {path: '/form/urgent'}}}},
            checks: [
              {condition: {call: 'required', args: {value: {path: '/form/subject'}}, returnType: 'boolean'}, message: 'Enter a subject first'},
              {condition: {call: 'length', args: {value: {path: '/form/subject'}, min: 4}, returnType: 'boolean'}, message: 'Subject must be at least 4 characters'},
            ],
          },
          {id: 'send-txt', component: 'Text', text: 'Send'},
        ],
      },
    },
    {version: 'v0.9', updateDataModel: {surfaceId: 'dm_form', path: '/', value: {username: '@sarahchen', form: {subject: '', tone: ['friendly'], urgent: false}}}},
  ],
};

export const SCENARIOS: Scenario[] = [composerScenario, customScenario, formScenario];
